package org.schoolkernel.workspace;

import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import com.microsoft.playwright.APIResponse;
import com.microsoft.playwright.options.RequestOptions;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

class DefinitionReviewBrowserIT extends WorkbenchBrowserSupport {
    @Test void completeDiffPresenceContextsAndReadingNeverMutates(){
        initial();open();ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy(),draft=doc.withObject("definitionDraft"),def=draft.withObject("definition");def.put("displayName","Authored school");((ObjectNode)def.path("teachers").get(0)).putArray("availablePeriodIds");((ObjectNode)def.path("lessons").get(0)).put("teacherId","literal-missing-teacher").put("seriesId","new-series");def.withArray("subjects").addObject().put("id","new-subject").put("displayName","<script>literal</script>");((tools.jackson.databind.node.ArrayNode)def.path("lessons")).remove(1);draft.withObject("editingContext").withObject("authoredLocks").withObject("lesson-math-1").put("periodLock","mon-2");draft.withObject("editingContext").withObject("requirements").putObject("new-series").put("seriesId","new-series").put("count","unfinished count").putObject("exceptions").putArray("lesson-math-1").add("teacherId");draft.put("draftRevision",DefinitionDraftService.revision(def));store("DEFINITION_DRAFT",doc);workbench.reload();String before=storedDocument();JsonNode review=review();assertEquals(storedVersion(),review.path("version").longValue());assertEquals("Authored school",review.path("draftIdentity").path("displayName").asString());assertTrue(review.path("changes").toString().contains("literal-missing-teacher"));assertTrue(review.path("changes").toString().contains("Cancelled"));assertTrue(review.path("changes").toString().contains("editingContext.authoredLocks"));assertTrue(review.path("issues").toString().contains("unfinished")||review.path("issues").toString().contains("nonnegative integer"));JsonNode issue=review.path("issues").valueStream().filter(row->row.path("ownerType").asString().equals("Lesson")&&row.path("field").asString().equals("teacherId")).findFirst().orElseThrow();assertEquals("lesson-math-1",issue.path("relatedLessonIds").get(0).asString());assertEquals("literal-missing-teacher",issue.path("causalEdits").get(0).path("after").asString());assertEquals(before,storedDocument());page().locator("#review-search").fill("not present anywhere");workbench.awaitText("0 of "+review.path("issues").size()+" saved issues shown");page().locator("#review-changes summary").click();assertEquals(before,storedDocument());assertEquals(review,review());page().locator("#review-search").fill("");page().locator("#review-changes summary").click();page().getByText("<script>literal</script>",new com.microsoft.playwright.Page.GetByTextOptions().setExact(false)).first().waitFor();assertEquals(before,storedDocument());
    }
    @Test void samePeriodIdTimingEveryAffectedLessonAndAddedCancelledSides(){
        storeAccepted(fixtures.validAcceptedDocument());workbench.open();open();ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy(),def=doc.withObject("definitionDraft").withObject("definition");ObjectNode first=(ObjectNode)def.path("periods").get(0);first.put("weekday","TUESDAY").put("order",2).put("startTime","09:00").put("endTime","09:45");JsonNode cancelled=def.path("lessons").get(1).deepCopy();((tools.jackson.databind.node.ArrayNode)def.path("lessons")).remove(1);def.withArray("lessons").add(((ObjectNode)def.path("lessons").get(0)).deepCopy().put("id","new-lesson").put("displayName","New occurrence"));doc.withObject("definitionDraft").put("draftRevision",DefinitionDraftService.revision(def));store("DEFINITION_DRAFT",doc);workbench.reload();String before=storedDocument();JsonNode review=review();assertEquals(3,review.path("timingImpacts").size());JsonNode math=review.path("timingImpacts").valueStream().filter(row->row.path("lessonId").asString().equals("lesson-math-1")).findFirst().orElseThrow();assertEquals("MONDAY",math.path("oldTiming").path("weekday").asString());assertEquals("TUESDAY",math.path("potentialTiming").path("weekday").asString());assertEquals(2,math.path("potentialTiming").path("order").intValue());assertEquals("09:00",math.path("potentialTiming").path("startTime").asString());assertFalse(math.path("periodIdMove").booleanValue());assertFalse(math.path("roomMove").booleanValue());assertEquals("mon-1",math.path("sourcePlacement").path("periodId").asString());JsonNode added=review.path("timingImpacts").valueStream().filter(row->row.path("lessonId").asString().equals("new-lesson")).findFirst().orElseThrow();assertFalse(added.has("sourcePlacement"));assertFalse(added.has("potentialTiming"));JsonNode removed=review.path("timingImpacts").valueStream().filter(row->row.path("lessonId").equals(cancelled.path("id"))).findFirst().orElseThrow();assertTrue(removed.has("oldTiming"));assertFalse(removed.has("potentialTiming"));workbench.awaitText("Timing changed at same period ID");workbench.awaitText("Added — no accepted placement");assertEquals(before,storedDocument());for(var entry:doc.path("definitionDraft").path("sourceDocument").properties())assertEquals(entry.getValue(),storedWorkspaceDocument().path(entry.getKey()));
    }
    @Test void issuesOrderExactAcrossReloadRestartAndNarrowFilteredReadOnly()throws Exception{
        initial();open();ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy(),def=doc.withObject("definitionDraft").withObject("definition");((ObjectNode)def.path("teachers").get(0)).putArray("availablePeriodIds");((ObjectNode)def.path("cohorts").get(0)).put("displayName","");doc.withObject("definitionDraft").put("draftRevision",DefinitionDraftService.revision(def));store("DEFINITION_DRAFT",doc);workbench.reload();JsonNode review=review();assertTrue(review.path("counts").path("blockers").longValue()>0);assertTrue(review.path("counts").path("advisories").longValue()>0);assertEquals("BLOCKING",review.path("issues").get(0).path("severity").asString());assertEquals("ADVISORY",review.path("issues").get(review.path("issues").size()-1).path("severity").asString());String before=storedDocument();page().locator("#review-severity").selectOption("ADVISORY");workbench.awaitText(review.path("counts").path("advisories").asString()+" of "+review.path("issues").size()+" saved issues shown");for(int width:List.of(390,700)){workbench.viewport(width,844);workbench.expect("document.documentElement.scrollWidth <= innerWidth && !!document.querySelector('#review-severity')");assertEquals(before,storedDocument());}workbench.viewport(1280,800);workbench.reload();assertEquals(review,review());assertEquals(before,storedDocument());try(var restarted=startRestartableWorkspace()){workbench.open(((org.springframework.boot.web.server.context.WebServerApplicationContext)restarted).getWebServer().getPort());assertEquals(before,storedDocument());assertEquals(review,JSON.readTree(page().request().get(page().url().replace("/workspace/","/api/workspace")).text()).path("definitionReview"));}
    }
    @Test void exactLinkedTargetRemovedAndStaleRefreshNeverOpenUnrelatedRecord(){
        initial();open();ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy(),def=doc.withObject("definitionDraft").withObject("definition");def.withArray("teachers").add(((ObjectNode)def.path("teachers").get(0)).deepCopy().put("id","teacher-blair").put("displayName","Blair"));((ObjectNode)def.path("teachers").get(1)).put("displayName","Authored Blair");doc.withObject("definitionDraft").put("draftRevision",DefinitionDraftService.revision(def));store("DEFINITION_DRAFT",doc);workbench.reload();String before=storedDocument();page().locator("button[data-review-type='Teacher'][data-review-id='teacher-blair']").first().click();page().locator("#teacher-id").waitFor();assertEquals("teacher-blair",page().locator("#teacher-id").inputValue());assertEquals(before,storedDocument());page().locator("button[data-section='Review']").click();doc=((ObjectNode)storedWorkspaceDocument()).deepCopy();((tools.jackson.databind.node.ArrayNode)doc.path("definitionDraft").path("definition").path("teachers")).remove(1);store("DEFINITION_DRAFT",doc);before=storedDocument();page().locator("button[data-review-type='Teacher'][data-review-id='teacher-blair']").first().click();workbench.awaitText("no unrelated record was opened");assertEquals("Review",page().locator("#authoring-section h3").textContent());assertEquals(before,storedDocument());
        page().locator("#review-search").fill("");
        // Existing target with stale version must refresh review before any editor opens.
        doc=((ObjectNode)storedWorkspaceDocument()).deepCopy();((ObjectNode)doc.path("definitionDraft").path("definition").path("lessons").get(0)).put("displayName","New math name");doc.withObject("definitionDraft").put("draftRevision",DefinitionDraftService.revision(doc.path("definitionDraft").path("definition")));store("DEFINITION_DRAFT",doc);workbench.reload();assertEquals(200,command("school",JSON.readTree("{\"schoolId\":\"demo-school\",\"displayName\":\"New school title\"}")).status());before=storedDocument();page().locator("button[data-review-type='Lesson'][data-review-id='lesson-math-1']").first().click();workbench.awaitText("Review the refreshed item before editing");assertEquals("Review",page().locator("#authoring-section h3").textContent());assertEquals(before,storedDocument());
    }
    @Test void emptyAndUnsavedReviewHasNoInventedPlacementOrUnsavedMutation(){
        workbench.open();open();page().locator("button[data-section='Review']").click();JsonNode review=review();assertEquals(0,review.path("timingImpacts").size());workbench.awaitText("No lessons configured; planning will produce an empty timetable");String before=storedDocument();page().locator("button[data-section='School']").click();page().locator("#school-display-name").fill("Unsaved school title");page().locator("button[data-section='Review']").click();page().locator("#school-stay").click();assertEquals("Unsaved school title",page().locator("#school-display-name").inputValue());assertEquals(before,storedDocument());page().locator("button[data-section='Review']").click();page().locator("#school-discard-working").click();assertFalse(page().locator("#review-changes").textContent().contains("Unsaved school title"));assertEquals(before,storedDocument());
    }
    @Test void policyTargetAndColdOccurrenceIssueLinksFocusExactControlsWithoutMutation(){
        initial();open();ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy(),def=doc.withObject("definitionDraft").withObject("definition");
        ((ObjectNode)def.path("lessons").get(0)).put("teacherId","missing-teacher");
        def.putArray("roomAssignments").addObject().put("id","unfinished-policy").put("subjectId","math");
        doc.withObject("definitionDraft").put("draftRevision",DefinitionDraftService.revision(def));store("DEFINITION_DRAFT",doc);workbench.reload();String before=storedDocument();
        page().getByText("Open issue: Lesson lesson-math-1 • teacherId",new com.microsoft.playwright.Page.GetByTextOptions().setExact(true)).first().click();
        page().locator("#occurrence-form").waitFor();workbench.expect("document.activeElement?.id === 'occurrence-teacherId-mode'");assertEquals(before,storedDocument());
        page().locator("button[data-section='Review']").click();page().getByText("Open issue: RoomAssignment unfinished-policy • target",new com.microsoft.playwright.Page.GetByTextOptions().setExact(true)).first().click();
        page().locator("#room-policy-form").waitFor();workbench.expect("document.activeElement?.id === 'room-policy-target-mode'");assertEquals("unfinished-policy",page().locator("#room-policy-id").inputValue());assertEquals(before,storedDocument());
    }
    private void initial(){ObjectNode def=((ObjectNode)fixtures.validAcceptedDocument().path("acceptedBaseline").path("definition")).deepCopy().put("catalogVersion",9);ObjectNode doc=JSON.createObjectNode();doc.set("initialDefinition",def);store("INITIAL_DRAFT",doc);workbench.open();}
    private void open(){page().locator("#open-authoring").click();page().locator("#confirm-authoring").click();workbench.awaitText("Saved school-definition draft");}
    private com.microsoft.playwright.Page page(){return workbench.page();}
    private JsonNode review(){return JSON.readTree(page().request().get("http://localhost:"+port+"/api/workspace").text()).path("definitionReview");}
    private void store(String state,JsonNode document){jdbc.sql("UPDATE workspace_aggregate SET lifecycle_state=:state,version=version+1,active_run_id=NULL,document=CAST(:document AS jsonb) WHERE workspace_id=1").param("state",state).param("document",JSON.writeValueAsString(document)).update();}
    private APIResponse command(String route,JsonNode body){String base="http://localhost:"+port;JsonNode csrf=JSON.readTree(page().request().get(base+"/api/csrf").text());return page().request().post(base+"/api/definition-draft/"+route,RequestOptions.create().setHeader("Content-Type","application/json").setHeader("Origin",base).setHeader(csrf.path("headerName").asString(),csrf.path("token").asString()).setHeader("If-Match","\"ws-"+storedVersion()+"\"").setData(JSON.writeValueAsString(body)));}
}
